// Mantem apenas faturas novas (sem .json correspondente no Drive).
// Items chegam do Dedup na ordem [texto..., visao...] — reconstruimos a lista
// consolidada na MESMA ordem, consultando cada consolidador so se executou.
const checks = $input.all();
function safe(n) { try { return $(n).all().map(x => x.json); } catch (e) { return []; } }
const consolidados = safe('Consolidar JSON (texto)').concat(safe('Consolidar JSON'));
const results = [];
let skipped = 0;
for (let i = 0; i < checks.length; i++) {
  const existe = checks[i].json && checks[i].json.files && checks[i].json.files.length > 0;
  if (existe) { skipped++; continue; }
  const orig = consolidados[i];
  if (!orig) continue;
  results.push({ json: orig });
}
if (results.length > 0 && results[0].json._summary) {
  results[0].json._summary = Object.assign({}, results[0].json._summary, { duplicados: skipped });
}
console.log('dedup: novos=' + results.length + ' duplicados=' + skipped);
return results;

const items = $input.all();
const results = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const jsonStr = JSON.stringify(item.json.record, null, 2);
  const buf = Buffer.from(jsonStr, 'utf8');
  const binaryData = await this.helpers.prepareBinaryData(buf, item.json.uploadName, 'application/json');
  results.push({
    json: { uploadName: item.json.uploadName, parsedOk: item.json.parsedOk, _summary: item.json._summary },
    binary: { data: binaryData }
  });
}
return results;

const novos = $input.all().length;
const cons = $('So Novos').all();
const parts = [];
for (const c of cons) {
  const s = c.json._summary || {};
  const cur = s.currency ? (' ' + s.currency) : '';
  const total = (s.total !== null && s.total !== undefined) ? s.total.toFixed(2) : '?';
  const w = s.warnings ? (' [!' + s.warnings + ']') : '';
  parts.push('• ' + (s.issuer || '?') + ' — ' + (s.file || '?') + ' → ' + (s.transactions || 0) + ' transacoes, total' + cur + ' ' + total + ', vence ' + (s.due || '?') + (s.parsedOk ? '' : ' [PARSE FALHOU]') + w);
}
const message = '💳 Fatura processada (' + novos + ' nova(s)):\n' + parts.join('\n');
return [{ json: { message, novos } }];

// Markdown-first: toolbox /markdown extrai GFM deterministico do text layer.
// Fallback para visao cobre: PDF encriptado (/markdown nao aceita password -> 400),
// scan sem text layer (DOCUMENT_NEEDS_OCR) e qualquer outro erro do endpoint.
const items = $input.all();
const orig = $('Config e Filtrar PDFs').all();
const out = [];
let md = 0, vis = 0;
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json || {};
  const meta = j._meta || {};
  const base = {
    msgId: meta.msgId, emailDate: meta.emailDate, fileName: meta.fileName,
    from: meta.from, subject: meta.subject, issuer: meta.issuer, password: meta.password
  };
  if (!base.msgId && orig[i] && orig[i].json) Object.assign(base, orig[i].json);
  const mdText = typeof j.markdown === 'string' ? j.markdown : null;
  if (mdText && mdText.length > 200) {
    md++;
    out.push({ json: Object.assign(base, { markdown: mdText, route: 'markdown' }) });
  } else {
    vis++;
    const bin = (item.binary && item.binary.data) || (orig[i] && orig[i].binary && orig[i].binary.data);
    out.push({ json: Object.assign(base, { route: 'vision', markdownError: (j.error && j.error.code) || 'sem markdown' }), binary: bin ? { data: bin } : {} });
  }
}
console.log('markdown-first: markdown=' + md + ' visao=' + vis);
return out;

// Markdown-first: toolbox /markdown extrai GFM deterministico do text layer.
// Etiqueta cada item com route ('markdown' | 'vision'); o Switch 'Rotear Caminho'
// divide. Fallback visao cobre: PDF encriptado (/markdown nao aceita password -> 400),
// scan sem text layer (DOCUMENT_NEEDS_OCR) e qualquer outro erro do endpoint.
const items = $input.all();
const orig = $('Config e Filtrar PDFs').all();
const out = [];
let md = 0, vis = 0;
for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const j = item.json || {};
  const meta = j._meta || {};
  const base = {
    msgId: meta.msgId, emailDate: meta.emailDate, fileName: meta.fileName,
    from: meta.from, subject: meta.subject, issuer: meta.issuer, password: meta.password
  };
  if (!base.msgId && orig[i] && orig[i].json) Object.assign(base, orig[i].json);
