const SCHEMA_TEXT = [
  'Voce e um extrator preciso de faturas/extratos de cartao de credito de QUALQUER banco (Portugal ou Brasil).',
  'Voce recebe o CONTEUDO TEXTUAL da fatura em markdown, extraido deterministicamente do PDF (text layer). Os numeros no markdown sao EXATOS — transcreva-os sem recalcular nem corrigir.',
  'Devolva EXATAMENTE um objeto JSON valido, sem markdown, sem comentarios.',
  '',
  'Schema:',
  '{',
  '  "schema": "card_statement_v1",',
  '  "issuer": string|null,',
  '  "currency": string|null,',
  '  "card_holder": string|null,',
  '  "card_last4": string|null,',
  '  "statement_period": { "open_date": "YYYY-MM-DD"|null, "close_date": "YYYY-MM-DD"|null },',
  '  "due_date": "YYYY-MM-DD"|null,',
  '  "payment_reference": string|null,',
  '  "total_balance": number|null,',
  '  "minimum_payment": number|null,',
  '  "previous_balance": number|null,',
  '  "credits_payments": number|null,',
  '  "credit_limit": number|null,',
  '  "available_limit": number|null,',
  '  "transactions": [',
  '    {',
  '      "date": "YYYY-MM-DD"|null,',
  '      "description": string,',
  '      "merchant": string|null,',
  '      "category": string,',
  '      "amount": number,',
  '      "installment_info": string|null,',
  '      "foreign_amount": number|null,',
  '      "foreign_currency": string|null',
  '    }',
  '  ],',
  '  "warnings": [string]',
  '}',
  '',
  'Regras:',
  '- issuer: nome do banco/emissor como aparece no documento (ex: XP, Nubank, Millennium BCP, Revolut).',
  '- currency: codigo ISO 4217 detectado no documento (BRL, EUR, USD...). Se ambiguo, null + warning.',
  '- category e UMA de: mercado, restaurante, transporte, assinaturas, saude, educacao, casa, viagem, tecnologia, lazer, vestuario, servicos_bancarios, taxas, saque, pagamento, outros.',
  '- Numeros com ponto decimal, sem simbolos. "R$ 1.234,56" -> 1234.56; "$1,234.56" -> 1234.56.',
  '- Datas YYYY-MM-DD; ano implicito => ano do periodo.',
  '- NAO invente valores; ilegivel => null + warnings. Campo ausente no documento => null.',
  '- SINAL (CRITICO): uma COMPRA tem amount SEMPRE POSITIVO. Muitos documentos mostram debitos com sinal negativo (ex: "-186,92" ou "186,92-"): NESSES casos INVERTA o sinal na extracao -> amount 186.92. Apenas estornos/ajustes a favor do cliente ficam NEGATIVOS.',
  '- PAGAMENTOS (CRITICO): linhas do tipo "PAGAMENTO RECEBIDO", "DEBITO DIRETO", "PAGAMENTO DO CARTAO" que liquidam a fatura NUNCA entram em transactions - NEM DUPLICADAS. Elas existem APENAS no campo credits_payments (numero POSITIVO). Confira: se uma linha de transactions tem valor igual ao total da fatura e descricao de pagamento, remova-a.',
  '- card_last4: os 4 ULTIMOS digitos do numero do cartao exibido (ex: "**** 1100" -> "1100"). Sem cartao no documento => null. NUNCA use "0000" como placeholder.',
  '- minimum_payment: se o documento nao exibir pagamento minimo e o total for liquidado por debito direto, use o valor de total_balance.',
  '- EXTRATO COMBINADO (CRITICO): se o documento misturar conta a ordem e cartao, localize a SECCAO do cartao de credito e extraia APENAS dela. Salario, depositos, transferencias e saldo da conta a ordem ficam FORA do JSON.',
  '- Cada linha de transacao = um objeto; "Parcela X/Y" em installment_info.',
  '- Compras em moeda estrangeira: valor convertido em amount, original em foreign_amount/foreign_currency.',
  '- Ignore rodapes de marketing, SAC, Ouvidoria, avisos legais.',
  '- AUTO-CHECAGEM: soma(transactions) - credits_payments deve aproximar total_balance (+/- previous_balance). Se nao fechar, reveja antes de responder.',
  '- Responda SOMENTE o JSON.',
].join('\n');

// Roteamento v5 (trial): 3 tiers por emissor.
const LOCAL_ISSUERS = new Set(['universo', 'xp']);            // mini, sempre disponivel
const LOCAL_HEAVY_ISSUERS = new Set(['millennium', 'bcp']);   // MacBook qwen3.8:27b

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const mdText = item.json.markdown || '';
  if (!mdText || mdText.length < 200) {
    results.push({ json: Object.assign({}, item.json, { skipped: true, skipReason: 'sem markdown' }), pairedItem: { item: i } });
    continue;
  }
  const issuerKey = String(item.json.issuer || '').toLowerCase();
  let engine = 'cloud';
  if (LOCAL_ISSUERS.has(issuerKey)) engine = 'local';
  else if (LOCAL_HEAVY_ISSUERS.has(issuerKey)) engine = 'local-heavy';

  let hint = SCHEMA_TEXT;
  if (item.json.issuer && item.json.issuer !== 'desconhecido') {
    hint += '\n- Dica: este documento deve ser do emissor "' + item.json.issuer + '".';
  }
  const content = [{ type: 'text', text: hint + '\n\nDOCUMENTO (markdown):\n' + mdText }];
  const MODEL = engine === 'local-heavy' ? 'qwen3.8:27b'
    : engine === 'local' ? 'gemma4-e4b-nothink'
    : 'glm-4.7';
  const reqBody = { model: MODEL, messages: [{ role: 'user', content }], temperature: 0, max_tokens: 12000 };
  const buf = Buffer.from(JSON.stringify(reqBody), 'utf8');
  const bin = await this.helpers.prepareBinaryData(buf, 'llm_body.json', 'application/json');
  results.push({
    json: Object.assign({}, item.json, { skipped: false, engine, engine_used: MODEL }),
    binary: { reqbody: bin },
    pairedItem: { item: i }
  });
}
